//! 既存整数解から既存box下降と同じ手順を試す独立診断。
use mip_codex::{heuristic::Repair,solve::Result};
fn main(){let a:Vec<_>=std::env::args().collect();if a.get(1).is_some_and(|v|v=="build-info"){println!("{}",serde_json::json!({"source_directory":env!("CARGO_MANIFEST_DIR"),"source_fingerprint":mip_codex::BUILD_SOURCE_FINGERPRINT,"library_source_directory":mip_codex::BUILD_SOURCE_DIRECTORY,"library_source_fingerprint":mip_codex::BUILD_SOURCE_FINGERPRINT}));return;}let m=mip_codex::mps::read(&a[1]).unwrap();let input:serde_json::Value=serde_json::from_reader(std::fs::File::open(&a[2]).unwrap()).unwrap();let seed:Vec<_>=m.variables.iter().map(|v|input["values"][&v.name].as_f64().unwrap()).collect();let repair=Repair::new(&m);let seconds:f64=a[3].parse().unwrap();let end=std::time::Instant::now()+std::time::Duration::from_secs_f64(seconds);let(x,stats)=repair.descend(&seed,end).unwrap();assert!(repair.candidate_check(&x));let r=Result{status:"feasible_primal_descent_diagnostic".into(),objective:Some(m.objective(&x)),values:Some(m.variables.iter().zip(x).map(|(v,x)|(v.name.clone(),x)).collect()),box_primal:stats,..Result::default()};serde_json::to_writer(std::fs::File::create(&a[4]).unwrap(),&r).unwrap();println!("{}",serde_json::json!({"objective":r.objective,"stats":r.box_primal,"source_fingerprint":mip_codex::BUILD_SOURCE_FINGERPRINT}));}
